INSERT INTO picture360_images (examId, specialty, conditionName, imageUrl, keyFeatures, examPearl, optionA, optionB, optionC, optionD, correctAnswer, explanation, status) VALUES
(1, 'Paediatrics', 'Eczema Herpeticum', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/paeds_eczema-herpeticum-placeholder.webp', 'Widespread monomorphic punched-out erosions and vesicles on a background of atopic eczema; may have haemorrhagic crusting; clustered vesicles that coalesce; child is systemically unwell with fever; rapidly progressive', 'Eczema herpeticum is a dermatological emergency caused by disseminated herpes simplex virus in a child with atopic eczema. It requires urgent IV aciclovir. Do not use topical steroids until HSV is treated. It can be life-threatening if untreated. Swab for viral PCR to confirm HSV', 'Disseminated HSV infection in atopic eczema requiring urgent IV aciclovir', 'Infected eczema from Staphylococcus aureus', 'Chickenpox', 'Impetigo', 'A', 'Eczema herpeticum is a medical emergency caused by disseminated herpes simplex virus infection in a child with pre-existing atopic eczema. It presents with widespread monomorphic punched-out erosions and vesicles, often with haemorrhagic crusting. The child is systemically unwell. Treatment is urgent IV aciclovir. Topical corticosteroids should be withheld until the HSV infection is controlled. Viral swab for PCR confirms the diagnosis. It can be life-threatening if untreated due to viraemia and secondary bacterial infection.', 'active'),
(1, 'Paediatrics', 'Mumps', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/paeds_mumps-placeholder.webp', 'Bilateral or unilateral parotid gland swelling giving a hamster-cheek appearance; tender swollen parotid glands obscuring the angle of the jaw; fever and malaise; trismus from parotid inflammation; may have submandibular gland involvement', 'Mumps is caused by a paramyxovirus. Complications include orchitis (post-pubertal males, usually unilateral — rarely causes infertility), meningitis, encephalitis, pancreatitis, and sensorineural hearing loss. Mumps is notifiable. MMR vaccine provides prevention. Exclusion from school for 5 days from onset of parotid swelling', 'Paramyxovirus infection causing parotid gland swelling', 'Bacterial parotitis', 'Parotid gland tumour', 'Sjogren syndrome', 'A', 'Mumps is caused by a paramyxovirus and presents with painful bilateral parotid gland swelling, fever, and malaise. It is spread by respiratory droplets with an incubation period of 14-21 days. Complications include orchitis (post-pubertal males), meningitis, encephalitis, pancreatitis, and sensorineural hearing loss. Diagnosis is clinical, confirmed by salivary or urine PCR. Treatment is supportive. MMR vaccine provides prevention. It is a notifiable disease.', 'active'),
(1, 'Paediatrics', 'Rubella', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/paeds_rubella-placeholder.webp', 'Fine pink maculopapular rash starting on the face and spreading to the trunk and limbs; rash lasts 3 days (hence German measles or three-day measles); postauricular and suboccipital lymphadenopathy; low-grade fever; arthralgia in older children and adults', 'Rubella is usually mild in children but devastating in pregnancy. Congenital rubella syndrome causes sensorineural deafness, cataracts, congenital heart defects (PDA, pulmonary stenosis), and microcephaly. Rubella in pregnancy before 16 weeks carries the highest risk. MMR vaccine provides prevention. It is a notifiable disease', 'Togavirus infection with rash, lymphadenopathy, and risk in pregnancy', 'Measles', 'Scarlet fever', 'Roseola infantum', 'A', 'Rubella (German measles) is caused by a togavirus. It presents with a fine pink maculopapular rash starting on the face and spreading downward, lasting about 3 days. Postauricular and suboccipital lymphadenopathy is characteristic. It is usually mild in children but congenital rubella syndrome (infection in pregnancy, especially before 16 weeks) causes sensorineural deafness, cataracts, congenital heart defects (PDA, pulmonary stenosis), and microcephaly. MMR vaccine provides prevention.', 'active'),
(1, 'Paediatrics', 'Pertussis', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/paeds_pertussis-placeholder.webp', 'Paroxysmal coughing fits followed by an inspiratory whoop; post-tussive vomiting; cough lasting more than 2 weeks; subconjunctival haemorrhages from coughing; apnoeic episodes in young infants; lymphocytosis on blood count', 'Pertussis (whooping cough) is caused by Bordetella pertussis. Three phases: catarrhal (1-2 weeks, most infectious), paroxysmal (2-8 weeks, characteristic whoop), and convalescent (weeks to months). Infants under 3 months may not whoop — they present with apnoea. Macrolide antibiotics (azithromycin) reduce infectivity but do not shorten the illness if given in the paroxysmal phase', 'Bordetella pertussis infection with paroxysmal cough and inspiratory whoop', 'Viral croup', 'Bronchiolitis', 'Foreign body aspiration', 'A', 'Pertussis (whooping cough) is caused by Bordetella pertussis. It has three phases: catarrhal (coryzal symptoms, most infectious), paroxysmal (characteristic paroxysmal cough with inspiratory whoop and post-tussive vomiting), and convalescent (gradual resolution over weeks to months). Young infants may present with apnoea rather than whooping. Diagnosis is by nasopharyngeal PCR or culture. Macrolide antibiotics reduce transmission but do not shorten illness in the paroxysmal phase. Vaccination provides prevention.', 'active'),
(1, 'Paediatrics', 'Rickets', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/paeds_rickets-placeholder.webp', 'Bowing of the legs (genu varum); widened wrists from metaphyseal expansion; rachitic rosary (swelling at costochondral junctions); frontal bossing; delayed fontanelle closure; Harrison sulcus (indentation of the lower ribs at the diaphragm attachment); X-ray shows cupping and fraying of metaphyses', 'Rickets is caused by vitamin D deficiency leading to defective mineralisation of growing bone. Risk factors include dark skin, exclusively breastfed infants without supplementation, limited sun exposure, and malabsorption. Biochemistry shows low calcium, low phosphate, raised ALP, raised PTH, and low 25-hydroxyvitamin D. Treatment is vitamin D supplementation', 'Defective bone mineralisation from vitamin D deficiency in children', 'Osteogenesis imperfecta', 'Scurvy', 'Physiological bowing', 'A', 'Rickets results from defective mineralisation of growing bone due to vitamin D deficiency. Clinical features include bowing of the legs, widened wrists, rachitic rosary, frontal bossing, and delayed fontanelle closure. X-rays show cupping, fraying, and widening of the metaphyses. Biochemistry shows low calcium, low phosphate, raised alkaline phosphatase, raised PTH, and low 25-hydroxyvitamin D. Treatment is vitamin D supplementation. Prevention includes vitamin D supplementation for all breastfed infants.', 'active'),
(1, 'Paediatrics', 'Osteogenesis Imperfecta', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/paeds_osteogenesis-imperfecta-placeholder.webp', 'Multiple fractures with minimal trauma; blue sclerae; short stature; joint hypermobility; dentinogenesis imperfecta (opalescent teeth); hearing loss; wormian bones on skull X-ray; osteopenia on X-ray', 'Osteogenesis imperfecta is a genetic disorder of type I collagen. Type I is the mildest and most common (blue sclerae, fractures, normal stature). Type II is lethal perinatally. Type III is the most severe surviving form (progressive deformity). Must be distinguished from non-accidental injury — skeletal survey and genetic testing help differentiate. Bisphosphonates reduce fracture frequency', 'Genetic collagen disorder causing brittle bones and blue sclerae', 'Non-accidental injury', 'Rickets', 'Osteopetrosis', 'A', 'Osteogenesis imperfecta (brittle bone disease) is a genetic disorder of type I collagen synthesis. It presents with recurrent fractures from minimal trauma, blue sclerae, short stature, joint hypermobility, and dentinogenesis imperfecta. Type I is the mildest and most common form. It must be distinguished from non-accidental injury — genetic testing and clinical features help differentiate. Treatment includes bisphosphonates to increase bone density and reduce fracture frequency, physiotherapy, and orthopaedic management.', 'active'),
(1, 'Paediatrics', 'Down Syndrome facial features', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/paeds_down-syndrome-placeholder.webp', 'Upslanting palpebral fissures; epicanthic folds; flat nasal bridge; protruding tongue; small ears; single palmar crease; sandal gap (wide gap between first and second toes); hypotonia in infancy; Brushfield spots on the iris', 'Down syndrome (trisomy 21) is the most common chromosomal disorder. Associated conditions include congenital heart defects (AVSD most common, 40-50%), duodenal atresia, Hirschsprung disease, hypothyroidism, leukaemia (ALL and AML), and Alzheimer disease. Screening is offered to all pregnant women (combined test at 11-14 weeks)', 'Trisomy 21 with characteristic facial features and associated anomalies', 'Turner syndrome', 'Williams syndrome', 'Noonan syndrome', 'A', 'Down syndrome (trisomy 21) is the most common chromosomal abnormality, with an incidence of approximately 1 in 700 live births. Characteristic features include upslanting palpebral fissures, epicanthic folds, flat nasal bridge, single palmar crease, and hypotonia. Associated conditions include congenital heart defects (AVSD most common), duodenal atresia, hypothyroidism, and increased risk of leukaemia. Antenatal screening is offered to all pregnant women. Life expectancy has improved significantly with modern medical care.', 'active'),
(1, 'Paediatrics', 'Turner Syndrome', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/paeds_turner-syndrome-placeholder.webp', 'Short stature (most common presenting feature); webbed neck; wide-spaced nipples (shield chest); lymphoedema of hands and feet in neonates; cubitus valgus (increased carrying angle); low posterior hairline; streak gonads causing primary amenorrhoea', 'Turner syndrome (45,X) affects 1 in 2500 live female births. Associated conditions include coarctation of the aorta (most common cardiac defect), bicuspid aortic valve, horseshoe kidney, hypothyroidism, and recurrent otitis media. Growth hormone therapy improves final height. Oestrogen replacement is needed for pubertal development. Fertility is possible with donor eggs', 'Monosomy X causing short stature and gonadal dysgenesis in females', 'Noonan syndrome', 'Down syndrome', 'Klinefelter syndrome', 'A', 'Turner syndrome (45,X) affects approximately 1 in 2500 live female births. The most common presenting feature is short stature. Other features include webbed neck, shield chest, lymphoedema, cubitus valgus, and primary amenorrhoea from streak gonads. Associated conditions include coarctation of the aorta, bicuspid aortic valve, horseshoe kidney, and hypothyroidism. Management includes growth hormone therapy for short stature and oestrogen replacement for pubertal development. Fertility may be achieved with donor oocytes.', 'active'),
(1, 'Paediatrics', 'Neonatal Jaundice', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/paeds_neonatal-jaundice-placeholder.webp', 'Yellow discolouration of the skin and sclera in a newborn; progresses cephalocaudally (face first, then trunk, then limbs); physiological jaundice peaks at day 2-3 in term infants; pathological if onset within 24 hours, prolonged beyond 14 days, or associated with pale stools and dark urine', 'Jaundice within 24 hours of birth is always pathological — the most common cause is haemolytic disease (ABO or Rhesus incompatibility, G6PD deficiency). Prolonged jaundice beyond 14 days requires investigation including conjugated bilirubin to exclude biliary atresia (pale stools, dark urine, hepatomegaly). Treatment is phototherapy; exchange transfusion for severe cases', 'Unconjugated hyperbilirubinaemia in the newborn period', 'Biliary atresia', 'Hepatitis', 'Sepsis', 'A', 'Neonatal jaundice is extremely common, affecting 60% of term and 80% of preterm infants. Physiological jaundice appears after 24 hours, peaks at day 2-3, and resolves by day 14. Jaundice within 24 hours is always pathological (haemolytic disease). Prolonged jaundice beyond 14 days requires investigation including split bilirubin to exclude biliary atresia. Treatment is phototherapy based on treatment threshold charts. Exchange transfusion is reserved for severe cases at risk of kernicterus.', 'active'),
(1, 'Paediatrics', 'Congenital Hypothyroidism', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/paeds_congenital-hypothyroidism-placeholder.webp', 'Prolonged neonatal jaundice; large fontanelles; macroglossia; umbilical hernia; constipation; poor feeding; hypotonia; coarse facial features; dry skin; hoarse cry; growth failure if untreated', 'Congenital hypothyroidism is detected by the newborn blood spot screening test (Guthrie test, day 5). It affects approximately 1 in 3000 newborns. The most common cause is thyroid dysgenesis. Early treatment with levothyroxine prevents intellectual disability. Without treatment, it causes cretinism with severe developmental delay', 'Thyroid hormone deficiency detected on newborn screening', 'Down syndrome', 'Beckwith-Wiedemann syndrome', 'Prader-Willi syndrome', 'A', 'Congenital hypothyroidism affects approximately 1 in 3000 newborns and is detected by the newborn blood spot screening test at day 5. The most common cause is thyroid dysgenesis. Clinical features include prolonged jaundice, macroglossia, umbilical hernia, constipation, hypotonia, and poor feeding. Early treatment with levothyroxine is essential to prevent irreversible intellectual disability. Most children treated early achieve normal cognitive development. Lifelong thyroid hormone replacement is required.', 'active');
